/*!
 * Password Caliper — a hover widget that docks a photographic vernier
 * caliper onto a password field, its jaws spanning the actual rendered
 * width of the masking dots, while its LCD reveals the hidden typeset
 * width the dots are disguising (press Option/Alt to toggle mm/inch).
 *
 * Usage:
 *   <script src="caliper-widget.js"></script>
 *   <script>PasswordCaliper.attach(document.querySelector('input[type=password]'));</script>
 *
 * Or auto-attach to every password field on the page:
 *   PasswordCaliper.attachAll();
 *
 * No external assets, no network requests except the optional DSEG7 font
 * (falls back to a plain monospace font if that fails to load).
 */
(function (global) {
  'use strict';

  const ASSETS = {"hook": "", "rodShaft": "", "rodTip": "", "leftcap": "", "beamExt": "", "rightcap": "", "sliderMain": ""};

  const CSS = `
  .pcal-cursor{
    position:fixed;
    top:0; left:0;
    width:430px;
    height:132px;
    pointer-events:none;
    z-index:2147483647;
    transform:translateY(-72px);
    display:none;
    filter:drop-shadow(0 6px 10px rgba(0,0,0,0.5));
    font-family:'Inter','Arial',sans-serif;
  }
  .pcal-leftcap{ position:absolute; top:0; left:0; width:300px; height:132px; }
  .pcal-beam-ext{
    position:absolute; top:36px; left:300px; height:26px; width:0px;
    background-repeat:repeat-x; background-size:auto 26px; will-change:width;
  }
  .pcal-rightcap{ position:absolute; top:0; left:300px; width:100px; height:132px; will-change:left; }
  .pcal-slider-hook{ position:absolute; top:2px; left:34px; width:26px; height:33px; will-change:transform; }
  .pcal-slider-hook-img{ position:absolute; top:0; left:0; width:26px; height:33px; }
  .pcal-slider-group{ position:absolute; top:2px; left:34px; width:149px; height:130px; will-change:transform; }
  .pcal-slider-img{ position:absolute; top:0; left:0; width:149px; height:130px; }
  .pcal-lcd-patch{
    position:absolute; left:34px; top:34px; width:55px; height:19px;
    display:flex; align-items:center; justify-content:flex-end;
    padding-right:2px; box-sizing:border-box;
  }
  .pcal-lcd-text{ display:flex; align-items:baseline; gap:1px; }
  .pcal-lcd-digits{
    font-family:'DSEG7 Classic Mini','Share Tech Mono',monospace;
    font-weight:700; font-size:11px; color:#2E3B29; letter-spacing:0.01em;
  }
  .pcal-lcd-unit{
    font-family:'Inter','Arial',sans-serif; font-weight:600;
    font-style:italic; font-size:7px; color:#2E3B29;
  }
  .pcal-rod-wrap{ position:absolute; left:398px; top:45px; height:8px; }
  .pcal-rod-shaft{
    position:absolute; top:0; left:0; height:8px; width:0px;
    background-repeat:repeat-x; background-size:auto 8px; will-change:width;
  }
  .pcal-rod-tip{ position:absolute; top:-1px; left:0; height:10px; will-change:left; }
  `;

  const FONT_CSS = `
  @font-face{
    font-family:'DSEG7 Classic Mini';
    font-style:normal;
    font-weight:700;
    font-display:swap;
    src:url(https://cdn.jsdelivr.net/fontsource/fonts/dseg7-classic-mini@latest/latin-700-normal.woff2) format('woff2');
  }
  `;

  let fontFaceInjected = false;
  function injectFontFaceOnce(){
    if(fontFaceInjected) return;
    const s = document.createElement('style');
    s.textContent = FONT_CSS;
    document.head.appendChild(s);
    fontFaceInjected = true;
  }

  function b64img(key){ return 'data:image/png;base64,' + ASSETS[key]; }

  function buildDom(){
    const wrap = document.createElement('div');
    wrap.className = 'pcal-cursor';
    wrap.innerHTML = `
      <div class="pcal-slider-hook">
        <img class="pcal-slider-hook-img" src="${b64img('hook')}" alt="">
      </div>
      <div class="pcal-rod-wrap">
        <div class="pcal-rod-shaft" style="background-image:url(${b64img('rodShaft')});"></div>
        <img class="pcal-rod-tip" src="${b64img('rodTip')}" alt="">
      </div>
      <img class="pcal-leftcap" src="${b64img('leftcap')}" alt="">
      <div class="pcal-beam-ext" style="background-image:url(${b64img('beamExt')});"></div>
      <img class="pcal-rightcap" src="${b64img('rightcap')}" alt="">
      <div class="pcal-slider-group">
        <img class="pcal-slider-img" src="${b64img('sliderMain')}" alt="">
        <div class="pcal-lcd-patch">
          <span class="pcal-lcd-text"><span class="pcal-lcd-digits">0.0</span><span class="pcal-lcd-unit">mm</span></span>
        </div>
      </div>
    `;
    return wrap;
  }

  // measurement helpers
  const measureCanvas = document.createElement('canvas');
  const measureCtx = measureCanvas.getContext('2d');

  function fontOf(el){
    const cs = getComputedStyle(el);
    return {
      font: `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`,
      letterSpacing: parseFloat(cs.letterSpacing) || 0
    };
  }

  function measureTypeWidth(text, el){
    if(!text) return 0;
    const {font, letterSpacing} = fontOf(el);
    measureCtx.font = font;
    const chars = Array.from(text);
    let total = 0;
    for(const ch of chars) total += measureCtx.measureText(ch).width;
    total += letterSpacing * Math.max(chars.length - 1, 0);
    return total;
  }

  const FONT_PROPS = ['fontSize','fontFamily','fontWeight','fontStyle','fontStretch','fontVariant','letterSpacing'];

  function measureDotAdvance(el){
    // This forces a real masked value into a deliberately too-narrow box and
    // reads the true overflowed content width (scrollWidth), rather than
    // inferring width from the `size` attribute. ScrollWidth
    // against real dot characters consistently lines up with the visible
    // dots instead.
    const cs = getComputedStyle(el);
    const make = (n) => {
      const t = document.createElement('input');
      t.type = 'password';
      t.value = 'a'.repeat(n);
      // Inline styles beat any external stylesheet selector on the host page
      // (e.g. a blanket `input{width:...}` reset), which would otherwise
      // silently override the forced narrow width and break this measurement.
      t.style.cssText = 'position:fixed !important; visibility:hidden !important; ' +
        'padding:0 !important; border:0 !important; margin:0 !important; ' +
        'width:1px !important; min-width:0 !important; max-width:none !important; ' +
        'box-sizing:content-box !important;';
      for(const prop of FONT_PROPS) t.style[prop] = cs[prop];
      document.body.appendChild(t);
      const w = t.scrollWidth;
      document.body.removeChild(t);
      return w;
    };
    return (make(15) - make(5)) / 10;
  }

  // the widget
  let CAL_CLOSED_DX = -32;     // value that actually closes correctly
  const CAL_ROD_FACTOR = 0.34;
  const PX_PER_MM = 10;
  const MM_PER_INCH = 25.4;
  const SLIDER_REL_X = 34;
  const SLIDER_WIDTH = 149;
  const LEFTCAP_WIDTH = 300;
  const ROD_OFFSET_INTO_TAIL = 97;
  const BEAM_MARGIN = 30;
  const JAW_INNER_EDGE_OFFSET = 24;
  const VERTICAL_NUDGE = 25;

  function attach(input, options){
    options = options || {};
    if(input.__pcalAttached) return input.__pcalController;
    input.__pcalAttached = true;

    // Everything below - injecting styles, building the DOM (which includes
    // decoding six embedded images) - is deferred until the first real hover.
    let cursorEl = null, host = null, sliderHook, sliderGroup, lcdDigits, lcdUnit,
        rodShaft, rodTip, rodWrap, beamExt, rightcap;

    function ensureDom(){
      if(cursorEl) return;
      injectFontFaceOnce();
      host = document.createElement('div');
      document.body.appendChild(host);
      const shadow = host.attachShadow({ mode: 'open' });
      const styleTag = document.createElement('style');
      styleTag.textContent = CSS;
      shadow.appendChild(styleTag);
      cursorEl = buildDom();
      shadow.appendChild(cursorEl);
      sliderHook = cursorEl.querySelector('.pcal-slider-hook');
      sliderGroup = cursorEl.querySelector('.pcal-slider-group');
      lcdDigits = cursorEl.querySelector('.pcal-lcd-digits');
      lcdUnit = cursorEl.querySelector('.pcal-lcd-unit');
      rodShaft = cursorEl.querySelector('.pcal-rod-shaft');
      rodTip = cursorEl.querySelector('.pcal-rod-tip');
      rodWrap = cursorEl.querySelector('.pcal-rod-wrap');
      beamExt = cursorEl.querySelector('.pcal-beam-ext');
      rightcap = cursorEl.querySelector('.pcal-rightcap');
    }

    let useInches = false;
    let hovering = false;

    function updateCursor(dotsWidthPx, typeWidthPx){
      const dx = CAL_CLOSED_DX + dotsWidthPx;
      const dxPx = `translateX(${dx}px)`;
      sliderGroup.style.transform = dxPx;
      sliderHook.style.transform = dxPx;

      if(useInches){
        lcdDigits.textContent = (typeWidthPx / PX_PER_MM / MM_PER_INCH).toFixed(4);
        lcdUnit.textContent = 'in';
      } else {
        lcdDigits.textContent = (typeWidthPx / PX_PER_MM).toFixed(1);
        lcdUnit.textContent = 'mm';
      }

      const sliderRightEdge = SLIDER_REL_X + dx + SLIDER_WIDTH;
      const extWidth = Math.max(0, sliderRightEdge + BEAM_MARGIN - LEFTCAP_WIDTH);
      beamExt.style.width = extWidth + 'px';
      rightcap.style.left = (LEFTCAP_WIDTH + extWidth) + 'px';
      rodWrap.style.left = (LEFTCAP_WIDTH + extWidth + ROD_OFFSET_INTO_TAIL) + 'px';

      const rodLen = Math.max(0, dotsWidthPx * CAL_ROD_FACTOR);
      rodShaft.style.width = rodLen + 'px';
      rodTip.style.left = rodLen + 'px';
      rodTip.style.visibility = rodLen > 1 ? 'visible' : 'hidden';
    }

    function positionCursor(){
      const rect = input.getBoundingClientRect();
      const cs = getComputedStyle(input);
      const padLeft = parseFloat(cs.paddingLeft) || 0;
      const borderLeft = parseFloat(cs.borderLeftWidth) || 0;
      const textStartX = rect.left + padLeft + borderLeft;
      cursorEl.style.left = (textStartX - JAW_INNER_EDGE_OFFSET) + 'px';
      cursorEl.style.top = (rect.top - VERTICAL_NUDGE) + 'px';
    }

    function refresh(){
      const dotAdvance = measureDotAdvance(input);
      const dotsWidth = Array.from(input.value).length * dotAdvance;
      const typeWidth = measureTypeWidth(input.value, input);
      updateCursor(dotsWidth, typeWidth);
    }

    function show(){
      ensureDom();
      hovering = true;
      positionCursor();
      refresh();
      cursorEl.style.display = 'block';
    }
    function hide(){ hovering = false; if(cursorEl) cursorEl.style.display = 'none'; }

    input.addEventListener('mouseenter', show);
    input.addEventListener('mouseleave', hide);
    input.addEventListener('input', () => { if(hovering) refresh(); });
    window.addEventListener('scroll', () => { if(hovering) positionCursor(); }, true);
    window.addEventListener('resize', () => { if(hovering) positionCursor(); });
    window.addEventListener('keydown', (e) => {
      if(e.key === 'Alt' && hovering){
        e.preventDefault();
        useInches = !useInches;
        refresh();
      }
    });

    const controller = {
      get element(){ return cursorEl; },
      show, hide, refresh,
      destroy(){
        input.removeEventListener('mouseenter', show);
        input.removeEventListener('mouseleave', hide);
        if(host) host.remove();
        input.__pcalAttached = false;
      }
    };
    input.__pcalController = controller;
    return controller;
  }

  function safeAttach(el){
    try { attach(el); }
    catch(err){ console.warn('[PasswordCaliper] failed to attach to', el, err); }
  }

  function attachAll(selector){
    selector = selector || 'input[type="password"]';
    document.querySelectorAll(selector).forEach(safeAttach);
    // watch for password fields added later (login modals, SPA navigation, etc.)
    // and for fields removed/replaced (some sites, notably banks, recreate the
    // password input on every keystroke as an anti-automation measure - without
    // this, each replacement would leave its old overlay orphaned on screen).
    const obs = new MutationObserver((mutations) => {
      for(const m of mutations){
        m.addedNodes.forEach(node => {
          if(node.nodeType !== 1) return;
          if(!node.isConnected) return;
          if(node.matches && node.matches(selector)) safeAttach(node);
          if(node.querySelectorAll) node.querySelectorAll(selector).forEach(safeAttach);
        });
        m.removedNodes.forEach(node => {
          if(node.nodeType !== 1) return;
          const cleanup = (el) => { if(el.__pcalController) el.__pcalController.destroy(); };
          if(node.matches && node.matches(selector)) cleanup(node);
          if(node.querySelectorAll) node.querySelectorAll(selector).forEach(cleanup);
        });
      }
    });
    obs.observe(document.documentElement, { childList: true, subtree: true });
    return obs;
  }

  global.PasswordCaliper = { attach, attachAll };
})(window);
